// Acceptance tests for lane cob-a (plan Tasks 2–5). Written by the orchestrator before dispatch.
// They go through the package entry point '@cob/core', the way the app and the agent import it.
// Do not edit this file; add your own tests in the per-module test files.
import { beforeEach, expect, test } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  CONFIRMED,
  CommandError,
  DataRepo,
  OwnershipError,
  PointSchema,
  UnsafeNameError,
  UnsupportedSchemaError,
  applyPointOp,
  createCommand,
  finishCommand,
  isSendable,
  queuedCommands,
  type Application,
  type Point,
} from '@cob/core';

const T0 = '2026-11-11T09:00:00.000Z';

const point = (o: Partial<Point> = {}): Point => ({
  id: 'p1',
  kind: 'skill',
  text: 'Forklift driving',
  rank: 100,
  rev: 1,
  evidence: { type: 'said', quote: 'i drive forklifts' },
  interviewId: 'i1',
  createdAt: T0,
  updatedAt: T0,
  ...o,
});

const application = (o: Partial<Application> = {}): Application => ({
  id: 'a1',
  organization: 'Example Foods',
  title: 'Warehouse supervisor',
  link: 'https://careers.example.com/jobs/1',
  state: 'parked',
  pendingSubmission: null,
  park: { type: 'captcha', at: T0 },
  parkHistory: [{ type: 'captcha', at: T0 }],
  submission: null,
  skip: null,
  statusNotes: [],
  closedAt: null,
  createdAt: T0,
  updatedAt: T0,
  ...o,
});

let dir: string;
let app: DataRepo;
let agent: DataRepo;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cob-acc-a-'));
  app = new DataRepo(dir, 'app');
  agent = new DataRepo(dir, 'agent');
});

test('B2 a point without evidence, with a fractional rank, or at revision 0 is rejected', () => {
  const { evidence: _evidence, ...noEvidence } = point();
  expect(PointSchema.safeParse(noEvidence).success).toBe(false);
  expect(PointSchema.safeParse(point({ rank: 100.5 })).success).toBe(false);
  expect(PointSchema.safeParse(point({ rev: 0 })).success).toBe(false);
  expect(PointSchema.safeParse(point()).success).toBe(true);
});

test('B4 each writer can only write what it owns, and anyone can read', () => {
  expect(() => agent.put('point', point())).toThrow(OwnershipError);
  expect(() => app.put('application', application())).toThrow(OwnershipError);
  app.put('point', point());
  agent.put('application', application());
  expect(agent.get('point', 'p1')).toEqual(point());
  expect(app.get('application', 'a1')).toEqual(application());
});

test('B4 commands: the app creates, the agent finishes once, nobody deletes, history stays', () => {
  agent.put('application', application());
  const c = createCommand(app, { verb: 'drop', target: 'a1', payload: { reason: 'role closed' } });
  expect(() => agent.put('command', { ...c, id: 'made-by-agent' })).toThrow(OwnershipError);
  expect(() => app.put('command', { ...c, state: 'done' })).toThrow(OwnershipError);
  expect(finishCommand(agent, c.id, 'done', 'closed: dropped')).toMatchObject({ state: 'done', resultNote: 'closed: dropped' });
  expect(() => finishCommand(agent, c.id, 'done', 'again')).toThrow(CommandError);
  expect(() => agent.delete('command', c.id)).toThrow(OwnershipError);
  expect(app.get('command', c.id)).toMatchObject({ state: 'done' });
});

test('B5 a corrupt or invalid record file is reported, not thrown, and good records still load', () => {
  app.put('point', point({ id: 'good' }));
  fs.writeFileSync(path.join(dir, 'profile/points/bad.json'), '{oops');
  fs.writeFileSync(path.join(dir, 'profile/points/weird.json'), JSON.stringify({ id: 'weird' }));
  const { items, errors } = app.list('point');
  expect(items.map((p) => p.id)).toEqual(['good']);
  expect(errors.map((e) => path.basename(e.file)).sort()).toEqual(['bad.json', 'weird.json']);
});

test('B6 ids and blob paths cannot escape the repo', () => {
  expect(() => app.put('point', point({ id: '../escape' }))).toThrow(UnsafeNameError);
  expect(() => app.writeBlob('../escape.pdf', new Uint8Array([1]))).toThrow(UnsafeNameError);
  expect(fs.existsSync(path.join(dir, '..', 'escape.pdf'))).toBe(false);
});

test('B8 a repo written by another format version, or with an unreadable cob.json, is refused', () => {
  fs.writeFileSync(path.join(dir, 'cob.json'), JSON.stringify({ schemaVersion: 2, createdAt: T0 }));
  expect(() => new DataRepo(dir, 'app')).toThrow(UnsupportedSchemaError);
  expect(() => new DataRepo(dir, 'app')).toThrow(/version 2/);
  fs.writeFileSync(path.join(dir, 'cob.json'), '{not json');
  expect(() => new DataRepo(dir, 'app')).toThrow(UnsupportedSchemaError);
  fs.writeFileSync(path.join(dir, 'cob.json'), JSON.stringify({ schemaVersion: 1, createdAt: T0 }));
  expect(() => new DataRepo(dir, 'app')).not.toThrow();
});

test('B10 a correction gets a new revision at the starting Confirmed rank; unsure is not sendable', () => {
  const ctx = (interviewId: string) => ({ interviewId, now: T0, id: () => 'p9' });
  const added = applyPointOp(null, { op: 'add', kind: 'skill', text: 'Excel', evidence: { type: 'said', quote: 'excel' } }, ctx('i1'))!;
  expect(added).toMatchObject({ id: 'p9', rank: CONFIRMED, rev: 1 });
  const corrected = applyPointOp(
    { ...added, rank: CONFIRMED + 2 },
    { op: 'correct', pointId: 'p9', text: 'Excel and Google Sheets', evidence: { type: 'said', quote: 'excel and google sheets' } },
    ctx('i2'),
  )!;
  expect(corrected).toMatchObject({ id: 'p9', text: 'Excel and Google Sheets', rank: CONFIRMED, rev: 2, interviewId: 'i2' });
  const unsure = applyPointOp(corrected, { op: 'unsure', pointId: 'p9', evidence: { type: 'said', quote: 'not sure' } }, ctx('i3'))!;
  expect(isSendable(unsure)).toBe(false);
  expect(unsure.rev).toBe(2);
});

test('B11 queued commands come back oldest first and every target is checked', () => {
  agent.put('application', application());
  app.putSingleton('lanes', { lanes: [{ id: 'one-outreach', name: 'One outreach' }] });
  createCommand(app, { verb: 'done', target: 'a1', payload: {} }, new Date('2026-11-11T10:00:01Z'));
  createCommand(app, { verb: 'status', target: 'a1', payload: { kind: 'reply', text: 'Recruiter called' } }, new Date('2026-11-11T10:00:00Z'));
  expect(queuedCommands(app).map((c) => c.verb)).toEqual(['status', 'done']);
  expect(() => createCommand(app, { verb: 'retry', target: 'missing', payload: {} })).toThrow(CommandError);
  expect(() => createCommand(app, { verb: 'lane_done', target: 'nope', payload: { day: '2026-11-11' } })).toThrow(CommandError);
  expect(() => createCommand(app, { verb: 'run_role', target: 'a1', payload: { role: 'finder' } })).toThrow(CommandError);
  expect(() => createCommand(app, { verb: 'lane_done', target: 'one-outreach', payload: { day: '11/11/2026' } })).toThrow();
});
